package com.hmdp.ai.runtime.retrieval;

import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.shared.text.TextNormalizer;import com.hmdp.ai.domain.artifact.Citation;import com.hmdp.ai.domain.knowledge.*;import org.springframework.stereotype.Component;import java.util.*;import java.util.stream.Collectors;

@Component public class HybridRetriever implements KnowledgeRetriever {private final KnowledgeRepository repository;private final KnowledgeIndexPort index;private final EmbeddingGateway embeddings;private final TextNormalizer normalizer;private final RrfFusionRanker fusion;private final RerankService reranker;private final ContextCompressor compressor;private final CitationBuilder citations;private final ObjectMapper mapper;public HybridRetriever(KnowledgeRepository repository,KnowledgeIndexPort index,EmbeddingGateway embeddings,TextNormalizer normalizer,RrfFusionRanker fusion,RerankService reranker,ContextCompressor compressor,CitationBuilder citations,ObjectMapper mapper){this.repository=repository;this.index=index;this.embeddings=embeddings;this.normalizer=normalizer;this.fusion=fusion;this.reranker=reranker;this.compressor=compressor;this.citations=citations;this.mapper=mapper;}
    @Override
    public HybridRetrievalResult retrieve(String tenant,String workspace,String user,String knowledgeBaseId,Integer version,String query,Integer requestedTopK){if(query==null||query.trim().isEmpty())throw new IllegalArgumentException("query must not be empty");KnowledgeBaseVersion kb=repository.findPublishedVersion(tenant,workspace,knowledgeBaseId,version).orElseThrow(()->new IllegalArgumentException("published knowledge base version not found"));JsonNode policy=read(kb.getRetrievalPolicyJson());int vectorTop=Math.max(1,policy.path("vectorTopN").asInt(30)),lexicalTop=Math.max(1,policy.path("lexicalTopN").asInt(30)),finalTop=Math.max(1,Math.min(requestedTopK==null?policy.path("finalTopK").asInt(8):requestedTopK,50));String normalized=normalizer.searchText(query);List<String> queries=expand(query);List<float[]> queryVectors=embeddings.embed(tenant,workspace,kb.getEmbeddingModelProfileId(),queries,kb.getEmbeddingDimension());KnowledgeSearchScope scope=new KnowledgeSearchScope(tenant,workspace,knowledgeBaseId,kb.getIndexVersion(),user);List<List<IndexHit>> rankings=new ArrayList<>();for(int i=0;i<queries.size();i++){rankings.add(index.vectorSearch(scope,queryVectors.get(i),vectorTop));rankings.add(index.lexicalSearch(scope,normalizer.searchText(queries.get(i)),lexicalTop));}List<RrfFusionRanker.FusedHit> fused=fusion.fuse(rankings,60);List<String> ids=fused.stream().map(RrfFusionRanker.FusedHit::getChunkId).collect(Collectors.toList());Map<String,KnowledgeChunk> chunks=repository.findChunksByIds(tenant,workspace,ids).stream().collect(Collectors.toMap(KnowledgeChunk::getId,c->c));List<KnowledgeChunk> ordered=new ArrayList<>();List<RrfFusionRanker.FusedHit> available=new ArrayList<>();for(RrfFusionRanker.FusedHit hit:fused){KnowledgeChunk chunk=chunks.get(hit.getChunkId());if(chunk!=null){ordered.add(chunk);available.add(hit);}}List<Double> fallback=available.stream().map(RrfFusionRanker.FusedHit::getScore).collect(Collectors.toList());String rerankProfile=policy.path("rerankModelProfileId").asText(null);RerankOutcome outcome=reranker.rerank(tenant,workspace,rerankProfile,query,ordered,fallback);List<Candidate> candidates=new ArrayList<>();for(int i=0;i<ordered.size();i++){double rerank=i<outcome.getScores().size()?outcome.getScores().get(i):fallback.get(i);candidates.add(new Candidate(ordered.get(i),available.get(i),rerank));}candidates.sort(Comparator.comparingDouble((Candidate c)->c.rerank).reversed().thenComparing(c->c.chunk.getId()));Set<String> hashes=new HashSet<>();Map<String,Integer> perDocument=new HashMap<>();List<RetrievedChunk> results=new ArrayList<>();for(Candidate c:candidates){if(!hashes.add(c.chunk.getContentHash()))continue;if(perDocument.merge(c.chunk.getDocumentId(),1,Integer::sum)>3)continue;String text=compressor.compress(c.chunk.getContent(),query,Math.max(300,policy.path("maxContextCharsPerChunk").asInt(1200)));Citation citation=citations.build(c.chunk,c.rerank);Map<String,Object> metadata=metadata(c.chunk.getMetadataJson());double score="MODEL".equals(outcome.getMode())?c.rerank:c.hit.getScore();results.add(new RetrievedChunk(c.chunk,score,c.hit.getVectorScore(),c.hit.getLexicalScore(),c.rerank,text,metadata,citation));if(results.size()>=finalTop)break;}List<String>warnings=results.isEmpty()?Collections.singletonList("INSUFFICIENT_KNOWLEDGE_EVIDENCE"):Collections.emptyList();return new HybridRetrievalResult(results,outcome.getMode(),warnings);}
    private List<String> expand(String query){LinkedHashSet<String> values=new LinkedHashSet<>();values.add(query.trim());for(String part:query.split("[，,；;。?？!]")){String value=part.trim();if(value.length()>=4)values.add(value);if(values.size()>=3)break;}return new ArrayList<>(values);}
    private JsonNode read(String json){try{return mapper.readTree(json);}catch(Exception e){throw new IllegalStateException("retrieval policy is invalid",e);}}
    private Map<String,Object> metadata(String json){try{return mapper.readValue(json,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});}catch(Exception e){return Collections.emptyMap();}}
    private static final class Candidate{private final KnowledgeChunk chunk;private final RrfFusionRanker.FusedHit hit;private final double rerank;private Candidate(KnowledgeChunk chunk,RrfFusionRanker.FusedHit hit,double rerank){this.chunk=chunk;this.hit=hit;this.rerank=rerank;}}
}
